insert into public.diagnosis_trees(symptom_id,tree) values('ES-1', '{"start":"n1","nodes":{"n1":{"text":"에스라이트 조절 다이얼을 손가락으로 눌러보았을 때 (수동으로) 발광이 될까요?","options":[{"label":"네","next":"n2a"},{"label":"아니오","end":"as","note":"에스라이트 내부 부품의 문제로 수리가 필요합니다.","attachment":"📎 A/S 매뉴얼 (전달 예정)"}]},"n2a":{"text":"발광이 된다면 에스라이트 자체는 문제가 없고, 카메라와 에스라이트를 이어주는 핫슈 또는 핫슈 케이블 문제입니다. 핫슈 재접촉 후에도 동일할까요?","options":[{"label":"동일합니다","next":"n3a"},{"label":"해결되었습니다","end":"solved"}]},"n3a":{"text":"핫슈 자체의 문제이거나 핫슈 케이블의 문제일 수 있어요! 일단 핫슈를 먼저 교체 진행해볼까요? 여분의 핫슈가 없다면 다른 부스의 핫슈를 잠시 가져와서 교체 테스트 해봐도 됩니다.","options":[{"label":"동일합니다","next":"n4a"},{"label":"해결되었습니다","end":"solved"}]},"n4a":{"text":"핫슈의 문제는 아닌 것 같아요! 핫슈 케이블의 연결 문제인 것 같은데, 핫슈 케이블 재접촉 해볼 수 있을까요?","options":[{"label":"동일합니다","next":"n5a"},{"label":"해결되었습니다","end":"solved"}]},"n5a":{"text":"케이블의 불량인 것 같네요..! 케이블 교체 해볼 수 있을까요? 여분의 케이블이 없으시다면 다른 부스의 케이블을 가져와 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('ES-2', '{"start":"n1","nodes":{"n1":{"text":"에스라이트 측면에 전원 스위치가 ㅡ 자에 가있을까요? (ㅡ자 = 켜짐)","options":[{"label":"네","next":"n2a"},{"label":"아니오","next":"nsw"}]},"nsw":{"text":"전원 스위치를 ㅡ 자에 위치시켜주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n2a"}]},"n2a":{"text":"전원 스위치는 정상적으로 켜져 있군요! 그렇다면 전원 케이블의 문제일 수 있습니다. 전원 케이블이 꽂혀있는 에스라이트 쪽과 반대편 멀티탭 쪽 재접촉 해봐주세요!","options":[{"label":"동일합니다","next":"n3a"},{"label":"해결되었습니다","end":"solved"}]},"n3a":{"text":"멀티탭의 문제일 수 있습니다. 전원 케이블을 다른 멀티탭 구로 이동시켜 꽂아볼 수 있을까요?","options":[{"label":"동일합니다","next":"n4a"},{"label":"해결되었습니다","end":"solved"}]},"n4a":{"text":"전원 케이블의 문제인 것 같네요, 전원 케이블 교체하여 테스트 부탁드립니다! 이 전원 케이블은 프린터 전원 케이블과 사양이 동일합니다. 여분이 없다면 다른 부스의 전원 케이블을 가져와 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"as","note":"전원 케이블 교체 시에도 해결되지 않는다면 에스라이트의 문제입니다. 에스라이트 전원부의 문제로 A/S가 필요합니다.","attachment":"📎 A/S 매뉴얼 (전달 예정)"},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CL-1', '{"start":"n1","nodes":{"n1":{"text":"지속광 전원 케이블 재접촉 해볼 수 있을까요? 지속광에 접촉된 연결부와 키오스크 측면 멀티탭에 연결되어 있는 전원 케이블 두 곳 모두 확인 부탁드립니다.","options":[{"label":"동일합니다","next":"n2a"},{"label":"멀티탭에 꽂히는게 아니라 어떤 기판에 접지되어 있어요","next":"n2b"},{"label":"해결되었습니다","end":"solved"}]},"n2a":{"text":"지속광 자체 문제 혹은 지속광 전원 케이블의 자체 문제일 수 있습니다. 우선 지속광 전원 케이블 먼저 교체 테스트 해볼 수 있을까요? 여분의 지속광 전원 케이블이 없다면 다른 부스의 전원 케이블을 가져와 교체 테스트 해주시면 됩니다.","options":[{"label":"동일합니다","next":"n3a"},{"label":"해결되었습니다","end":"solved"}]},"n3a":{"text":"지속광 자체의 문제로 확인됩니다. 여분의 지속광으로 교체 테스트 부탁드립니다. 여분이 없다면 다른 부스의 지속광 하나만 떼와서 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]},"n2b":{"text":"해당 사진과 같이 기판에 접지되어 있는 형태라면:\n1) 키오스크 PC 전원을 끈다\n2) 키오스크 차단기를 내린다\n3) 드라이버를 이용하여 피스를 풀어 해당 +와- 에 접지되어 있는 케이블을 뺐다가 다시 조여준다\n4) 역순으로 키오스크 전원 ON 하여 상태 확인","attachment":"📷 사진 첨부 예정","options":[{"label":"동일합니다","next":"n3b"},{"label":"해결되었습니다","end":"solved"}]},"n3b":{"text":"SMPS 기판의 문제일 확률이 큽니다. 하지만 지속광 자체의 문제일 가능성도 배제할 순 없어, 먼저 여분의 지속광으로 교체 테스트 부탁드립니다. 만약 여분의 지속광이 없다면 다른 부스의 지속광 하나만 떼와서 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate","note":"SMPS 기판 문제로 추정됩니다."},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CL-2', '{"start":"n1","nodes":{"n1":{"text":"지속광 전원 케이블 재접촉 해볼 수 있을까요? 지속광에 접촉된 연결부와 키오스크 측면 멀티탭에 연결되어 있는 전원 케이블 두 곳 모두 확인 부탁드립니다.","options":[{"label":"동일합니다","next":"n2a"},{"label":"멀티탭에 꽂히는게 아니라 어떤 기판에 접지되어 있어요","next":"n2b"},{"label":"해결되었습니다","end":"solved"}]},"n2a":{"text":"지속광 자체 문제 혹은 지속광 전원 케이블의 자체 문제일 수 있습니다. 우선 지속광 전원 케이블 먼저 교체 테스트 해볼 수 있을까요? 여분의 지속광 전원 케이블이 없다면 다른 부스의 전원 케이블을 가져와 교체 테스트 해주시면 됩니다.","options":[{"label":"동일합니다","next":"n3a"},{"label":"해결되었습니다","end":"solved"}]},"n3a":{"text":"지속광 자체의 문제로 확인됩니다. 여분의 지속광으로 교체 테스트 부탁드립니다. 여분이 없다면 다른 부스의 지속광 하나만 떼와서 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]},"n2b":{"text":"해당 사진과 같이 기판에 접지되어 있는 형태라면:\n1) 키오스크 PC 전원을 끈다\n2) 키오스크 차단기를 내린다\n3) 드라이버를 이용하여 피스를 풀어 해당 +와- 에 접지되어 있는 케이블을 뺐다가 다시 조여준다\n4) 역순으로 키오스크 전원 ON 하여 상태 확인","attachment":"📷 사진 첨부 예정","options":[{"label":"동일합니다","next":"n3b"},{"label":"해결되었습니다","end":"solved"}]},"n3b":{"text":"SMPS 기판의 문제일 확률이 큽니다. 하지만 지속광 자체의 문제일 가능성도 배제할 순 없어, 먼저 여분의 지속광으로 교체 테스트 부탁드립니다. 만약 여분의 지속광이 없다면 다른 부스의 지속광 하나만 떼와서 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate","note":"SMPS 기판 문제로 추정됩니다."},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CAM-1', '{"start":"n1","nodes":{"n1":{"text":"에러코드 몇 번일까요?","options":[{"label":"에러코드 01","next":"n01"},{"label":"에러코드 20","end":"as","note":"셔터박스, 미러박스 등 관련 오류로 인한 셔터 오작동 상태입니다. (A/S 필요)","attachment":"📎 A/S 매뉴얼 (전달 예정)"},{"label":"에러코드 30","end":"as","note":"셔터박스, 미러박스 등 관련 오류로 인한 셔터 오작동 상태입니다. (A/S 필요)","attachment":"📎 A/S 매뉴얼 (전달 예정)"},{"label":"에러코드 70","next":"n70"},{"label":"에러코드 99","end":"as","note":"기계부 구성 관련 오류입니다.","attachment":"📎 A/S 매뉴얼 (전달 예정)"}]},"n01":{"text":"카메라 렌즈 간의 결합 불완전으로 렌즈 재결합이 필요합니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]},"n70":{"text":"카메라 온도 문제입니다. 카메라 전원을 끈 상태로 5~10분 정도 대기 후, 다시 전원을 켜서 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"as","attachment":"📎 A/S 매뉴얼 (전달 예정)"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CAM-2', '{"start":"n1","nodes":{"n1":{"text":"뒷문을 열어 카메라 전원이 들어와있는지 확인해주세요 (아무것도 만지지 말고). 카메라 화면이 꺼져있다면 메뉴 버튼을 눌러서 전원이 들어오는지 확인해주세요.","options":[{"label":"들어옴","next":"n2a"},{"label":"안 들어옴","next":"n2b"}]},"n2a":{"text":"카메라에 에러코드가 떠있을까요?","options":[{"label":"예","jump":"CAM-1"},{"label":"아니오","next":"n3a"}]},"n3a":{"text":"기본세팅 확인 부탁드리고, 테더선 재접촉 후 테스트 부탁드립니다.","attachment":"📎 기본세팅 매뉴얼 (전달 예정)","options":[{"label":"동일합니다","next":"n4a"},{"label":"해결되었습니다","end":"solved"}]},"n4a":{"text":"테더선이 꽂힌 PC의 USB 포트를 다른 곳으로 위치 이동시켜서 꽂은 후 다시 테스트해주세요.","options":[{"label":"동일합니다","next":"n5a"},{"label":"해결되었습니다","end":"solved"}]},"n5a":{"text":"여분의 테더선으로 교체하여 테스트 부탁드립니다. 여분의 테더선이 없다면 다른 부스의 테더선을 가지고 와 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]},"n2b":{"text":"더미배터리 재접촉 후 카메라 전원이 들어오는지 확인 부탁드립니다. (카메라 접촉부, 멀티탭 접촉부 2곳 모두)","options":[{"label":"전원 들어옵니다","next":"n2c"},{"label":"동일합니다","next":"n3b"}]},"n3b":{"text":"더미배터리 콘센트가 꽂힌 멀티탭의 위치를 다른 곳으로 변경하여 꽂은 후 카메라 전원이 들어오는지 확인 부탁드립니다.","options":[{"label":"전원 들어옵니다","next":"n2c"},{"label":"동일합니다","next":"n4b"}]},"n4b":{"text":"더미배터리 교체 후 전원이 들어오는지 확인 부탁드립니다.","options":[{"label":"전원 들어옵니다","next":"n2c"},{"label":"동일합니다","end":"escalate"}]},"n2c":{"text":"에러코드 떠있을까요?","options":[{"label":"예","jump":"CAM-1"},{"label":"아니오","next":"n3c"}]},"n3c":{"text":"촬영 테스트 부탁드립니다.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"escalate"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CAM-3', '{"start":"n1","nodes":{"n1":{"text":"카메라 전원이 들어와있는지 확인해주세요 (아무것도 만지지 말고). 화면이 꺼져있다면 메뉴 버튼을 눌러서 전원이 들어오는지 확인해주세요.","options":[{"label":"들어옴","next":"n2a"},{"label":"안 들어옴","next":"n2b"}]},"n2a":{"text":"테더선 재접촉 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","next":"n3a"},{"label":"해결되었습니다","end":"solved"}]},"n3a":{"text":"테더선이 꽂힌 PC의 USB 포트를 다른 곳으로 위치 이동시켜서 꽂은 후 다시 테스트해주세요.","options":[{"label":"동일합니다","next":"n4a"},{"label":"해결되었습니다","end":"solved"}]},"n4a":{"text":"여분의 테더선으로 교체하여 테스트 부탁드립니다. 여분이 없다면 다른 부스의 테더선을 가지고 와 교체 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]},"n2b":{"text":"더미배터리 재접촉 (카메라측+멀티탭측) 후 전원이 들어오는지 확인 부탁드립니다.","options":[{"label":"전원 들어옵니다","next":"n3b"},{"label":"동일합니다","next":"n4b"}]},"n3b":{"text":"통신 테스트 부탁드립니다.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n4b"}]},"n4b":{"text":"멀티탭 위치 변경 후 확인 부탁드립니다.","options":[{"label":"전원 들어옵니다","next":"n3b"},{"label":"동일합니다","next":"n5b"}]},"n5b":{"text":"더미배터리 교체 후 확인 부탁드립니다.","options":[{"label":"전원 들어옵니다","next":"n3b"},{"label":"동일합니다","end":"escalate"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CAM-4', '{"start":"n1","nodes":{"n1":{"text":"해당 사진과 같이 매수 촬영을 1매 촬영으로 변경해주세요.","attachment":"📷 사진 첨부 예정","options":[{"label":"확인했습니다","end":"info","note":"설정값 조정으로 안내가 종료됩니다."}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CAM-5', '{"start":"n1","nodes":{"n1":{"text":"카메라 초점이 흐린가요?","options":[{"label":"예","next":"n2a"},{"label":"아니오","jump":"CAM-2"}]},"n2a":{"text":"렌즈와 아크릴을 마른천으로 잘 닦아주시고, 초점 모드가 AF로 되어 있는지 확인 부탁드립니다. 렌즈, 바디 재결합도 진행해주세요.","attachment":"📷 사진 첨부 예정","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CAM-6', '{"start":"n1","nodes":{"n1":{"text":"셔터박스 불량으로 인한 검은줄 증상으로 A/S가 필요합니다.","attachment":"📎 A/S 매뉴얼 (전달 예정)","options":[{"label":"확인했습니다","end":"as"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('CAM-7', '{"start":"n1","nodes":{"n1":{"text":"렌즈와 아크릴을 마른천으로 잘 닦아주시고, 초점 모드가 AF로 되어 있는지 확인 부탁드립니다. 렌즈, 바디 재결합도 진행해주세요.","attachment":"📷 사진 첨부 예정","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"escalate"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('MON-1', '{"start":"n1","nodes":{"n1":{"text":"화면 뒷편을 확인해보았을 때 초록 or 빨간 LED가 들어와있을까요?","options":[{"label":"예","next":"n2a"},{"label":"아니오","next":"n2b"}]},"n2a":{"text":"모니터의 전원 자체는 문제 없으므로 HDMI 재접촉 후 화면이 나오는지 확인 필요합니다.","options":[{"label":"동일합니다","next":"n3a"},{"label":"해결되었습니다","end":"solved"}]},"n3a":{"text":"HDMI 케이블 교체 이후 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]},"n2b":{"text":"모니터 전원 어댑터에 LED가 들어와있는지 확인 및 전원케이블 재접촉 필요합니다 (모니터측 + 멀티탭측).","options":[{"label":"동일합니다","next":"n3b"},{"label":"해결되었습니다","end":"solved"}]},"n3b":{"text":"전원 어댑터 + 전원 케이블 자체 교체가 필요합니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('MON-2', '{"start":"n1","nodes":{"n1":{"text":"모니터 뒷편 터치 케이블 재접촉 (모니터 접촉부와 PC 접촉부 2곳) 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","next":"n2"},{"label":"해결되었습니다","end":"solved"}]},"n2":{"text":"터치 케이블 교체 후 테스트 부탁드립니다. 여분의 터치케이블이 없다면 프린터 AB 케이블과 동일한 형태이므로 교체 테스트 필요합니다.","options":[{"label":"동일합니다","end":"as","note":"모니터 터치 패널 자체의 문제로 A/S가 필요합니다. 여분의 모니터로 교체 부탁드립니다.","attachment":"📎 A/S 매뉴얼 (전달 예정)"},{"label":"교체가 불가한 타입의 모니터입니다","end":"as","note":"모니터 자체 A/S가 필요합니다. 여분의 모니터로 교체 부탁드립니다.","attachment":"📎 A/S 매뉴얼 (전달 예정)"},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('MON-3', '{"start":"n1","nodes":{"n1":{"text":"HDMI 재접촉 후 테스트 부탁드립니다.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n2"}]},"n2":{"text":"HDMI 케이블 교체 후 테스트 부탁드립니다.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"as","note":"모니터 디스플레이 패널 자체 문제로 A/S가 필요합니다.","attachment":"📎 A/S 매뉴얼 (전달 예정)"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('PRT-1', '{"start":"n1","nodes":{"n1":{"text":"1. 전원 차단 및 헤드 식히기: 프린터 전원을 끄고 케이블을 분리한 후, 출력 직후라면 헤드가 뜨거우니 5~10분간 식혀주세요.\n2. 커버 개방 및 소모품 분리: 전면 커버를 열고 인화지, 리본을 모두 제거해 먼지·지문·스크래치를 확인합니다.\n3. 감열 헤드 청소: 소독용 알코올(이소프로필 90%↑)을 묻힌 세정펜 또는 보풀 없는 면봉으로 헤드(발열체) 부위를 한 방향으로 살살 문질러 닦습니다. ⚠️ 금속·딱딱한 도구는 절대 사용하지 마세요 (헤드 손상 시 영구 흰 선 발생).\n4. 롤러 청소: 인화지가 지나가는 롤러를 알코올 솜으로 닦고, 손으로 돌려가며 전체 면을 청소합니다.\n5. 인화지 앞부분 제거: 특정 자리에 반복적인 얼룩이 생긴다면 인화지 롤 바깥쪽 30~50cm를 잘라내고 재장착합니다.\n6. 건조 및 재가동 테스트: 알코올이 마를 때까지 1~2분 건조 후 재조립, 전원을 켜고 테스트 출력해 확인합니다.","attachment":"🎥 영상 매뉴얼 (전달 예정)","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n2"}]},"n2":{"text":"인화지, 리본을 새것으로 교체해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"as","attachment":"📎 A/S 매뉴얼 (전달 예정)"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
