insert into public.diagnosis_trees(symptom_id,tree) values('PRT-3', '{"start":"n1","nodes":{"n1":{"text":"키오스크 앞문을 열어 프린터 전면부 LED가 들어와있는지 확인 필요합니다.","options":[{"label":"들어와있음","next":"n2a"},{"label":"안 들어와있음","next":"n2b"}]},"n2a":{"text":"프린터 AB 케이블 재접촉 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","next":"n3a"},{"label":"해결되었습니다","end":"solved"}]},"n3a":{"text":"AB 케이블이 꽂혀있는 PC의 USB 포트 위치 변경 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","next":"n4a"},{"label":"해결되었습니다","end":"solved"}]},"n4a":{"text":"AB 케이블 교체 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]},"n2b":{"text":"프린터 전원 케이블 재접촉 (프린터 부분과 멀티탭 부분 2곳 모두) 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","next":"n3b"},{"label":"해결되었습니다","end":"solved"}]},"n3b":{"text":"전원 케이블이 꽂혀있는 멀티탭 위치 변경 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","next":"n4b"},{"label":"해결되었습니다","end":"solved"}]},"n4b":{"text":"전원 케이블 교체 후 테스트 부탁드립니다.","options":[{"label":"동일합니다","end":"escalate"},{"label":"해결되었습니다","end":"solved"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
insert into public.diagnosis_trees(symptom_id,tree) values('PRT-7', '{"start":"n1","nodes":{"n1":{"text":"PC 부분 랜선과 매장 벽포트에 접촉되어 있는 랜선, 두 곳 모두 재접촉 후 PC 재부팅 및 테스트 부탁드립니다.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n2"}]},"n2":{"text":"랜선 교체 후 테스트 부탁드립니다.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"escalate","note":"인터넷 기사를 호출하여 해당 부스의 인터넷 연결 상태 확인이 필요합니다."}]}}}'::jsonb) on conflict(symptom_id) do nothing;
