insert into public.diagnosis_trees(symptom_id,tree) values('BILL-1', '{"start":"n1","nodes":{"n1":{"text":"지폐투입기에 LED가 들어와있을까요?","options":[{"label":"네","next":"n2a"},{"label":"아니요","next":"n2b"}]},"n2a":{"text":"지폐투입기 상부 커버를 열었을 때 레일이 돌아가면서 소리가 나나요?","options":[{"label":"네","end":"escalate"},{"label":"아니요","next":"n3a"}]},"n3a":{"text":"레일을 수동으로 돌려가면서 이물질이 있는지 확인하고, 마른 천을 이용하여 청소 및 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"escalate"}]},"n2b":{"text":"지폐투입기 측면에 있는 케이블과, 그 반대쪽인 멀티탭과 PC 부분 or I/O 보드 기판 부분을 재접촉 후 LED가 들어오는지 확인해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n3b"}]},"n3b":{"text":"지폐투입기 또는 지폐투입기 케이블을 교체하여 테스트해주세요. 여분이 없다면 정상 작동하는 부스의 지폐투입기 혹은 케이블을 가져와 테스트해주세요. 교체 항목에 따라 조치되는 것을 보고 어떤 것이 불량인지 확인해주세요.","options":[{"label":"지폐투입기 교체로 해결되었습니다","end":"solved","note":"지폐투입기 불량으로 확인되었습니다."},{"label":"케이블 교체로 해결되었습니다","end":"solved","note":"케이블 불량으로 확인되었습니다."}]}}}'::jsonb) on conflict(symptom_id) do nothing;
