insert into public.diagnosis_trees(symptom_id,tree) values('RC-1', '{"start":"n1","nodes":{"n1":{"text":"키오스크 뒷문을 열어 좌측을 보면 리모컨이 빠져있는 구멍이 있습니다. 그 선을 따라가면 체결부가 있는데, 거기 재접촉 해서 작동되는지 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n2"}]},"n2":{"text":"이 키오스크는 I/O보드를 사용하는 타입인가요?","options":[{"label":"예, I/O보드형","next":"n3a"},{"label":"아니오, 최신형 (USB커넥터 통합)","next":"n3b"}]},"n3a":{"text":"서비스코인, 설정버튼이 작동되나요?","options":[{"label":"작동 안 함","end":"escalate","note":"I/O보드 문제로 판단됩니다. TX팀 소통에 따라 조치 방법을 안내받아야 합니다."},{"label":"작동함","next":"n4a"}]},"n4a":{"text":"리모컨 교체 후 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n5a"}]},"n5a":{"text":"리모컨 연장케이블 교체 후 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"escalate"}]},"n3b":{"text":"서비스코인, 설정버튼이 작동되나요?","options":[{"label":"작동함","next":"n4b"},{"label":"작동 안 함","next":"n4c"}]},"n4b":{"text":"리모컨 교체 후 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"escalate"}]},"n4c":{"text":"PC에 꽂혀있는 USB 커넥터 케이블(setting/coin 네임택) 재접촉 후 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","next":"n5c"}]},"n5c":{"text":"USB 커넥터 케이블 교체 후 테스트해주세요.","options":[{"label":"해결되었습니다","end":"solved"},{"label":"동일합니다","end":"escalate"}]}}}'::jsonb) on conflict(symptom_id) do nothing;
